function regexLogic(h) {
  const { T, V, set, D } = h; const pi = V._p ?? 0, P = D.x[pi]; const fl = V._fl || '100';
  const tog = (i) => set({ _fl: fl.slice(0, i) + (fl[i] === '1' ? '0' : '1') + fl.slice(i + 1) });
  let hits = 0;
  const lines = D.x[0].lines.map((ln, j) => { let m = null; try { m = new RegExp(P.src, fl[0] === '1' ? 'i' : '').exec(ln); } catch (e) { m = null; } if (m && m[0]) hits++; return { a: m && m[0] ? ln.slice(0, m.index) : ln, m: m && m[0] ? m[0] : '', b: m && m[0] ? ln.slice(m.index + m[0].length) : '', hit: !!(m && m[0]), style: '--j:' + j }; });
  return { lines, hits, total: lines.length, tokens: P.tok.map((t, j) => ({ label: t[0], note: T(t[1], t[2]), cls: 'tag ' + ['pri', 'ter', '', 'good', 'warn'][j % 5], style: '--j:' + j })), src: P.src,
    presets: D.x.map((p, i) => ({ label: T(p.n[0], p.n[1]), pressed: i === pi ? 'true' : 'false', pick: () => set({ _p: i }) })), pIdx: pi, pCnt: D.x.length,
    flags: [['Ignore case', '唔分大細楷'], ['All matches', '全部匹配'], ['Across lines', '跨行']].map((f, i) => ({ label: T(f[0], f[1]), cls: 'chip' + (fl[i] === '1' ? ' on' : ''), pressed: fl[i] === '1' ? 'true' : 'false', tog: () => tog(i) })) };
}
